from itertools import batched, chain, islice

logs = {"a.log": "INFO start\nERROR disk\n\nINFO ok\n",
        "b.log": "ERROR net\nERROR disk\nINFO bye\n"}
for name, text in logs.items():
    open(name, "w").write(text)

def read_lines(path):
    with open(path) as f:             # closed when the generator finishes
        for n, line in enumerate(f, 1):
            yield path, n, line.rstrip("\n")

lines = chain.from_iterable(read_lines(p) for p in logs)
records = ((p, n, *l.split(" ", 1)) for p, n, l in lines if l)
errors = (r for r in records if r[2] == "ERROR")
for batch in batched(islice(errors, 3), 2):
    print(batch)
# (('a.log', 2, 'ERROR', 'disk'), ('b.log', 1, 'ERROR', 'net'))
# (('b.log', 2, 'ERROR', 'disk'),)

def total_and_max(items):
    return sum(items), max(items, default=None)
print(total_and_max([3, 1, 4]))           # (8, 4)
print(total_and_max(iter([3, 1, 4])))     # (8, None)  -- exhausted by sum

def firsts(iterables):
    for it in iterables:
        yield next(iter(it))              # StopIteration on an empty one
try:
    list(firsts([[1], [], [3]]))
except RuntimeError as e:
    print(e)                              # generator raised StopIteration

factor = 2
doubled = (x * factor for x in [1, 2, 3])
factor = 10                               # changed before consumption
print(list(doubled))                      # [10, 20, 30]

a, b = iter([1, 2, 3]), iter(["x"])
print(list(zip(a, b)), list(a))           # [(1, 'x')] [3]  -- 2 was lost
